select page, case when duration_sec >= 366 then 'high' when duration_sec >= 137 then 'mid' else 'low' end as duration_sec_bucket, event_type, count(case when page = '/home' then 1 end) as home_count from web_events where duration_sec between 353 and 355 and duration_sec between 268 and 305 group by page, case when duration_sec >= 366 then 'high' when duration_sec >= 137 then 'mid' else 'low' end, event_type having home_count < 1;
